# =============================================================================
# Script: B_plot_gcta_heritability.R
#
# Purpose:
#   Plot GCTA REML variance component and heritability estimates with
#   approximate 95% confidence intervals, comparing females and males across
#   statin status and LDL-C phenotype.
#
# Input:
#   - gcta_reml_results.rds: Combined results tibble generated by
#     A_read_gcta_logs.R.
#
# Outputs:
#   - A three-panel ggplot object (p) comparing:
#       (a) Non-statin users with unadjusted LDL-C
#       (b) Statin users with unadjusted LDL-C
#       (c) Statin users with statin-adjusted LDL-C
#   - Panels display estimates for V(G), V(e), Vp, and V(G)/Vp, with
#     approximate 95% confidence intervals, stratified by sex.
#
# Methods:
#   - Recodes sex, statin status, and LDL-C phenotype labels for plotting.
#   - Reshapes variance component and heritability estimates into long format.
#   - Uses estimates and confidence intervals calculated by
#     A_read_gcta_logs.R.
#   - Automatically identifies whether the input results contain maximum-LDL
#     or non-maximum-LDL phenotypes and selects the corresponding panels.
#   - Displays female and male estimates separately, with females listed first.
#   - Combines the three panels vertically using patchwork.
#
# Notes:
#   - The script expects phenotype labels of unadj, adj, max_unadj, or max_adj
#     in the input tibble.
#   - The input results should contain the phenotype groups needed for all
#     three panels. The script stops with an error if a requested group is
#     absent.
#   - Confidence intervals are approximate normal-based intervals calculated
#     as estimate +/- 1.96 SE in A_read_gcta_logs.R.
#   - Run this script from a working directory containing
#     gcta_reml_results.rds.
# =============================================================================

# =============================================================================
# 0. SETUP
# =============================================================================

library(tidyverse)
library(patchwork)
results <- readRDS("gcta_reml_results.rds")

# =============================================================================
# 1. PREPARE RESULTS
# =============================================================================

plot_df <- results |>
  mutate(
    sex = recode(sex,
                 fem = "Female",
                 male = "Male"),
    
    statin_status = recode(statin_status,
                           stat = "Statin Users",
                           nostat = "Non-users"),
    
    # Preserve max versus non-max phenotype labels.
    ldl_type = recode(
      ldl_type,
      unadj = "Unadjusted LDL-C",
      adj = "Statin-adjusted LDL-C",
      max_unadj = "Max unadjusted LDL-C",
      max_adj = "Max statin-adjusted LDL-C"
    ),
    
    label = paste0(sex, "\n(n=", scales::comma(n), ")")
  ) |>
  select(
    sex, statin_status, ldl_type, label, n,
    VG, VG_lower, VG_upper,
    Ve, Ve_lower, Ve_upper,
    Vp, Vp_lower, Vp_upper,
    h2, h2_lower, h2_upper
  ) |>
  pivot_longer(
    cols = c(VG, Ve, Vp, h2),
    names_to = "component",
    values_to = "value"
  ) |>
  mutate(
    lower = case_when(
      component == "VG" ~ VG_lower,
      component == "Ve" ~ Ve_lower,
      component == "Vp" ~ Vp_lower,
      component == "h2" ~ h2_lower
    ),
    upper = case_when(
      component == "VG" ~ VG_upper,
      component == "Ve" ~ Ve_upper,
      component == "Vp" ~ Vp_upper,
      component == "h2" ~ h2_upper
    ),
    component = recode(
      component,
      VG = "V(G)",
      Ve = "V(e)",
      Vp = "Vp",
      h2 = "V(G)/Vp"
    ),
    component = factor(
      component,
      levels = c("V(G)/Vp", "V(G)", "V(e)", "Vp")
    ),
    sex = factor(sex, levels = c("Female", "Male"))
  )

# =============================================================================
# 2. PLOTTING FUNCTION
# =============================================================================

make_panel <- function(data, status, phenotype, panel_label) {
  
  d <- data |>
    filter(
      statin_status == status,
      ldl_type == phenotype
    ) |>
    mutate(
      label = factor(label, levels = rev(unique(label[order(sex)])))
    )
  
  if (nrow(d) == 0) {
    stop(
      paste(
        "No rows found for:", status, "|", phenotype,
        "\nAvailable combinations:",
        paste(
          unique(paste(data$statin_status, data$ldl_type, sep = " / ")),
          collapse = "; "
        )
      )
    )
  }
  
  ggplot(d, aes(x = value, y = label, color = sex, group = sex)) +
    geom_vline(
      data = d |> filter(component %in% c("V(G)", "V(G)/Vp")),
      aes(xintercept = 0),
      linetype = 2,
      color = "grey70"
    ) +
    geom_errorbar(
      aes(xmin = lower, xmax = upper),
      orientation = "y",
      width = 0.05,
      position = position_dodge(width = 0.5)
    ) +
    geom_point(
      size = 2.2,
      position = position_dodge(width = 0.5)
    ) +
    facet_wrap(~component, nrow = 1, scales = "free_x") +
    scale_color_manual(
      values = c("Female" = "#332288", "Male" = "#44AA99"),
      breaks = c("Female", "Male")
    ) +
    labs(
      subtitle = panel_label,
      x = "Estimate",
      y = NULL
    ) +
    theme_bw() +
    theme(
      legend.position = "none"
    )
}

# =============================================================================
# 3. DETERMINE WHICH PHENOTYPE SET IS PRESENT
# =============================================================================

is_max <- any(str_detect(plot_df$ldl_type, "^Max "))

if (is_max) {
  unadjusted <- "Max unadjusted LDL-C"
  adjusted <- "Max statin-adjusted LDL-C"
} else {
  unadjusted <- "Unadjusted LDL-C"
  adjusted <- "Statin-adjusted LDL-C"
}

# =============================================================================
# 4. CREATE PANELS A, B, AND C
# =============================================================================

# a. Non-statin users, unadjusted LDL-C
a <- make_panel(
  plot_df, "Non-users", unadjusted, "(a)"
)

# b. Statin users, unadjusted LDL-C
b <- make_panel(
  plot_df, "Statin Users", unadjusted, "(b)"
)

# c. Statin users, statin-adjusted LDL-C
c <- make_panel(
  plot_df, "Statin Users", adjusted, "(c)"
)

# =============================================================================
# 5. COMBINE PANELS
# =============================================================================

p <- a / b / c
p
